<?php
declare(strict_types=1);
require_once __DIR__ . '/_chrome.php';

if (!function_exists('crm_e')) { function crm_e($v): string { return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8'); } }
if (!function_exists('crm_company_id')) { function crm_company_id(): int { return defined('COMPANY_ID') ? (int)COMPANY_ID : 0; } }
if (!function_exists('crm_user_id')) { function crm_user_id(): int { return function_exists('auth_user_id') ? (int)(auth_user_id() ?? 0) : (int)($_SESSION['user_id'] ?? 0); } }
if (!function_exists('crm_csrf_token')) { function crm_csrf_token(): string { if(session_status()!==PHP_SESSION_ACTIVE)@session_start(); if(empty($_SESSION['csrf_crm']))$_SESSION['csrf_crm']=bin2hex(random_bytes(24)); return (string)$_SESSION['csrf_crm']; } }
if (!function_exists('crm_csrf_check')) { function crm_csrf_check(string $token): void { if($token==='' || !hash_equals(crm_csrf_token(),$token)) throw new RuntimeException('Sessão expirada. Atualize a página e tente novamente.'); } }
if (!function_exists('crm_date')) { function crm_date($v): string { $s=trim((string)$v); if($s==='')return '—'; $t=strtotime($s); return $t?date('d/m/Y',$t):$s; } }
if (!function_exists('crm_datetime')) { function crm_datetime($v): string { $s=trim((string)$v); if($s==='')return '—'; $t=strtotime($s); return $t?date('d/m/Y H:i',$t):$s; } }
if (!function_exists('crm_state_label')) { function crm_state_label(string $state): string { return strtoupper($state)==='CONCLUIDO'?'Concluído':'Pendente'; } }
if (!function_exists('crm_state_class')) { function crm_state_class(string $state): string { return strtoupper($state)==='CONCLUIDO'?'done':'pending'; } }
if (!function_exists('crm_clean_color')) { function crm_clean_color(string $color): string { $color=strtoupper(trim($color)); return preg_match('/^#[0-9A-F]{6}$/',$color)?$color:'#2563EB'; } }
if (!function_exists('crm_next_contact_default')) { function crm_next_contact_default(): string { return date('Y-m-d', strtotime('+1 day')); } }

if (!function_exists('crm_temperature_clamp')) { function crm_temperature_clamp($value): int { return max(0,min(100,(int)round((float)$value))); } }
if (!function_exists('crm_temperature_label')) { function crm_temperature_label($value): string { $v=crm_temperature_clamp($value); return $v<=33?'Frio':($v<=66?'Morno':'Quente'); } }
if (!function_exists('crm_temperature_color')) { function crm_temperature_color($value): string { $v=crm_temperature_clamp($value); if($v<=33)return '#2563EB'; if($v<=66)return '#F59E0B'; return '#DC2626'; } }
if (!function_exists('crm_temperature_badge')) { function crm_temperature_badge($value,bool $showScore=false): string { $v=crm_temperature_clamp($value);$label=crm_temperature_label($v);$color=crm_temperature_color($v);return '<span class="crm-temp-badge" style="--crm-temp-color:'.crm_e($color).'"><span aria-hidden="true">🌡️</span><strong>'.crm_e($label).'</strong>'.($showScore?'<small>'.$v.'%</small>':'').'</span>'; } }
if (!function_exists('crm_temperature_control')) {
function crm_temperature_control(string $name,$value,string $id='crmLeadTemperature'): void { $v=crm_temperature_clamp($value);$label=crm_temperature_label($v);$color=crm_temperature_color($v); ?>
<div class="crm-temp-control" data-crm-temperature style="--crm-temp-value:<?=$v?>%;--crm-temp-color:<?=crm_e($color)?>">
  <input type="hidden" name="<?=crm_e($name)?>" value="<?=$v?>" data-crm-temp-value>
  <div class="crm-temp-meter" aria-hidden="true"><div class="crm-temp-tube"><div class="crm-temp-fill"></div></div><div class="crm-temp-bulb"></div></div>
  <div class="crm-temp-main"><div class="crm-temp-current"><strong data-crm-temp-label><?=crm_e($label)?></strong><span data-crm-temp-score><?=$v?>%</span></div><input id="<?=crm_e($id)?>" type="range" min="0" max="100" step="5" value="<?=$v?>" data-crm-temp-range aria-label="Temperatura do lead"><div class="crm-temp-presets"><button type="button" class="crm-btn sm" data-crm-temp-set="20">Frio</button><button type="button" class="crm-btn sm" data-crm-temp-set="55">Morno</button><button type="button" class="crm-btn sm" data-crm-temp-set="90">Quente</button></div></div>
</div>
<?php }}


if (!function_exists('crm_seed_defaults')) {
function crm_seed_defaults(PDO $pdo,int $companyId): void {
  static $done=[]; if($companyId<=0 || isset($done[$companyId])) return; $done[$companyId]=true;
  try{
    $status=[['Novo','#2563EB',10],['Em atendimento','#F59E0B',20],['Aguardando retorno','#7C3AED',30],['Concluído','#16A34A',40]];
    $st=$pdo->prepare("INSERT INTO crm_statuses(company_id,name,color,active,sort_order,created_at) VALUES(?,?,?,1,?,NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name)");
    foreach($status as $r)$st->execute([$companyId,$r[0],$r[1],$r[2]]);
    $types=[['Telefone',10],['WhatsApp',20],['E-mail',30],['Presencial',40]];
    $tt=$pdo->prepare("INSERT INTO crm_service_types(company_id,name,active,sort_order,created_at) VALUES(?,?,1,?,NOW()) ON DUPLICATE KEY UPDATE name=VALUES(name)");
    foreach($types as $r)$tt->execute([$companyId,$r[0],$r[1]]);
  }catch(Throwable $e){ /* migration ainda não aplicada: a própria página de acesso exibirá a indisponibilidade */ }
}}

if (!function_exists('crm_statuses')) {
function crm_statuses(PDO $pdo,int $companyId,bool $activeOnly=true): array {
  crm_seed_defaults($pdo,$companyId);
  $sql='SELECT id,name,color,active,sort_order FROM crm_statuses WHERE company_id=?';
  if($activeOnly)$sql.=' AND active=1';
  $sql.=' ORDER BY sort_order,name,id';
  $st=$pdo->prepare($sql);$st->execute([$companyId]);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];
}}
if (!function_exists('crm_types')) {
function crm_types(PDO $pdo,int $companyId,bool $activeOnly=true): array {
  crm_seed_defaults($pdo,$companyId);
  $sql='SELECT id,name,active,sort_order FROM crm_service_types WHERE company_id=?';
  if($activeOnly)$sql.=' AND active=1';
  $sql.=' ORDER BY sort_order,name,id';
  $st=$pdo->prepare($sql);$st->execute([$companyId]);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];
}}
if (!function_exists('crm_users')) {
function crm_users(PDO $pdo,int $companyId,bool $activeOnly=true): array {
  $sql='SELECT id,name,email,is_active FROM users WHERE '.(function_exists('access_company_users_sql') ? access_company_users_sql($pdo) : '(company_id = ?)');if($activeOnly)$sql.=' AND is_active=1';$sql.=' ORDER BY name,id';
  $st=$pdo->prepare($sql);$st->execute((function_exists('access_company_users_params') ? access_company_users_params($pdo, $companyId) : [$companyId]));return $st->fetchAll(PDO::FETCH_ASSOC)?:[];
}}
if (!function_exists('crm_attendance')) {
function crm_attendance(PDO $pdo,int $companyId,int $id): array {
  if($id<=0)return[];
  $st=$pdo->prepare("SELECT a.*,s.name status_name,s.color status_color,t.name service_type_name,u.name responsible_name,cb.name created_by_name,cl.name closed_by_name
    FROM crm_attendances a
    LEFT JOIN crm_statuses s ON s.company_id=a.company_id AND s.id=a.status_id
    LEFT JOIN crm_service_types t ON t.company_id=a.company_id AND t.id=a.service_type_id
    LEFT JOIN users u ON u.company_id=a.company_id AND u.id=a.responsible_user_id
    LEFT JOIN users cb ON cb.company_id=a.company_id AND cb.id=a.created_by
    LEFT JOIN users cl ON cl.company_id=a.company_id AND cl.id=a.closed_by
    WHERE a.company_id=? AND a.id=? LIMIT 1");$st->execute([$companyId,$id]);return $st->fetch(PDO::FETCH_ASSOC)?:[];
}}
if (!function_exists('crm_moves')) {
function crm_moves(PDO $pdo,int $companyId,int $attendanceId): array {
  $st=$pdo->prepare("SELECT m.*,u.name responsible_name,c.name created_by_name FROM crm_attendance_moves m LEFT JOIN users u ON u.company_id=m.company_id AND u.id=m.responsible_user_id LEFT JOIN users c ON c.company_id=m.company_id AND c.id=m.created_by WHERE m.company_id=? AND m.attendance_id=? ORDER BY m.created_at DESC,m.id DESC");$st->execute([$companyId,$attendanceId]);return $st->fetchAll(PDO::FETCH_ASSOC)?:[];
}}

if (!function_exists('crm_grid_key')) {
function crm_grid_key(string $gridId,int $userId): string { $gridId=preg_replace('/[^a-z0-9_\-]/i','_',strtolower(trim($gridId)))?:'grid';return $userId>0?'ui_crm_grid_'.$gridId.'_user_'.$userId:''; }
}
if (!function_exists('crm_grid_preferences_normalize')) {
function crm_grid_preferences_normalize(array $prefs,array $allowed): array {
  $allowed=array_values(array_unique(array_map('strval',$allowed)));$visible=[];$order=[];$widths=[];
  foreach((array)($prefs['visible']??[]) as $c){$c=(string)$c;if(in_array($c,$allowed,true)&&!in_array($c,$visible,true))$visible[]=$c;}
  foreach((array)($prefs['order']??[]) as $c){$c=(string)$c;if(in_array($c,$allowed,true)&&!in_array($c,$order,true))$order[]=$c;}
  foreach((array)($prefs['widths']??[]) as $c=>$w){$c=(string)$c;$w=(int)$w;if(in_array($c,$allowed,true)&&$w>=50&&$w<=900)$widths[$c]=$w;}
  return ['visible'=>$visible,'order'=>$order,'widths'=>$widths];
}}
if (!function_exists('crm_grid_preferences_load')) {
function crm_grid_preferences_load(PDO $pdo,int $companyId,string $gridId,array $allowed): array {
  $uid=crm_user_id();$key=crm_grid_key($gridId,$uid);$d=['visible'=>$allowed,'order'=>$allowed,'widths'=>[],'saved'=>false];if($companyId<=0||$uid<=0||$key==='')return$d;
  try{$st=$pdo->prepare('SELECT cfg_json FROM app_config WHERE company_id=? AND cfg_key=? LIMIT 1');$st->execute([$companyId,$key]);$raw=$st->fetchColumn();if(!is_string($raw)||trim($raw)==='')return$d;$j=json_decode($raw,true);if(!is_array($j))return$d;$n=crm_grid_preferences_normalize($j,$allowed);if(!$n['visible'])$n['visible']=$allowed;if(!$n['order'])$n['order']=$allowed;$n['saved']=true;return$n;}catch(Throwable $e){return$d;}
}}
if (!function_exists('crm_grid_toolbar')) {
function crm_grid_toolbar(string $gridId,array $columns,array $prefs): void {$visible=(array)($prefs['visible']??array_keys($columns));$gid=crm_e($gridId);?>
<div class="crm-grid-toolbar no-print"><span class="crm-grid-hint">Arraste o cabeçalho para mover • arraste a borda para ajustar</span><span class="crm-grid-status" id="crmGridStatus-<?=$gid?>"><?=!empty($prefs['saved'])?'Layout salvo no usuário':''?></span><details class="crm-column-picker"><summary class="crm-btn sm">☷ Colunas</summary><div class="crm-column-menu"><strong>Colunas visíveis</strong><?php foreach($columns as $key=>$label):if($key==='acoes')continue;?><label><input type="checkbox" data-crm-column-toggle="<?=$gid?>" value="<?=crm_e($key)?>" <?=in_array($key,$visible,true)?'checked':''?>> <span><?=crm_e($label)?></span></label><?php endforeach;?><button class="crm-btn sm" type="button" data-crm-grid-reset="<?=$gid?>">Restaurar padrão</button></div></details></div>
<?php }}
if (!function_exists('crm_grid_script')) {
function crm_grid_script(string $gridId,array $columns,array $prefs,array $defaultWidths=[]): void {$allowed=array_keys($columns);$csrf=crm_csrf_token();?>
<script>
(()=>{const grid=document.getElementById(<?=json_encode('crmGrid-'.$gridId)?>);if(!grid)return;const gridId=<?=json_encode($gridId)?>,csrf=<?=json_encode($csrf)?>,available=<?=json_encode(array_values($allowed))?>,server=<?=json_encode($prefs,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>||{},defaults=<?=json_encode($defaultWidths)?>||{},actions='acoes',draggable=available.filter(c=>c!==actions);let visible=Array.isArray(server.visible)&&server.visible.length?available.filter(c=>server.visible.includes(c)):available.slice();if(!visible.length)visible=available.slice();let order=draggable.slice();if(Array.isArray(server.order)){const v=server.order.filter(c=>draggable.includes(c));order=v.concat(draggable.filter(c=>!v.includes(c)));}let widths=(server.widths&&typeof server.widths==='object'&&!Array.isArray(server.widths))?Object.assign({},server.widths):{};const status=document.getElementById('crmGridStatus-'+gridId),toggles=[...document.querySelectorAll('[data-crm-column-toggle="'+CSS.escape(gridId)+'"]')];let timer=null,seq=0;
const setStatus=(t,c='')=>{if(status){status.textContent=t||'';status.className='crm-grid-status'+(c?' '+c:'')}};const payload=()=>({visible:visible.filter(c=>available.includes(c)),order:order.filter(c=>draggable.includes(c)).concat([actions]),widths});async function save(){const my=++seq;setStatus('Salvando…','saving');try{const b=new URLSearchParams();b.set('csrf',csrf);b.set('grid_id',gridId);b.set('preferences',JSON.stringify(payload()));const r=await fetch('crm_grid_preferences.php',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/x-www-form-urlencoded;charset=UTF-8','X-Requested-With':'XMLHttpRequest'},body:b.toString()});const d=await r.json().catch(()=>({}));if(!r.ok||!d.ok)throw new Error(d.message||'Falha ao salvar');if(my===seq){setStatus('Salvo no usuário','saved');setTimeout(()=>{if(my===seq)setStatus('','')},1800)}}catch(e){if(my===seq)setStatus('Não foi possível salvar','error')}}const schedule=(ms=350)=>{clearTimeout(timer);timer=setTimeout(save,ms)};
function cols(c){return [...grid.querySelectorAll('[data-col="'+CSS.escape(c)+'"]')]}function applyVisible(){available.forEach(c=>cols(c).forEach(el=>el.classList.toggle('crm-col-hidden',c!==actions&&!visible.includes(c))));toggles.forEach(t=>t.checked=visible.includes(t.value));}function applyOrder(){const full=order.concat([actions]);[...grid.rows].forEach(row=>{const map={};[...row.children].forEach(cell=>{if(cell.dataset.col)map[cell.dataset.col]=cell});full.forEach(c=>{if(map[c])row.appendChild(map[c])})});}function widthFor(c){const n=Number(widths[c]??defaults[c]??0);return Number.isFinite(n)&&n>0?n:0}function applyWidths(){available.forEach(c=>{const w=widthFor(c);cols(c).forEach(el=>{el.style.width=w?w+'px':'';el.style.minWidth=w?w+'px':''})})}function applyWidth(c,w,commit=false){w=Math.max(50,Math.min(900,Math.round(w)));widths[c]=w;cols(c).forEach(el=>{el.style.width=w+'px';el.style.minWidth=w+'px'});if(commit)schedule(60)}
applyOrder();applyVisible();applyWidths();toggles.forEach(t=>t.addEventListener('change',()=>{visible=toggles.filter(x=>x.checked).map(x=>x.value);if(!visible.length){t.checked=true;visible=[t.value]}applyVisible();schedule()}));let dragging=null,after=false;const clear=()=>grid.querySelectorAll('.crm-drop-before,.crm-drop-after,.crm-dragging').forEach(x=>x.classList.remove('crm-drop-before','crm-drop-after','crm-dragging'));draggable.forEach(c=>{const th=grid.querySelector('thead th[data-col="'+CSS.escape(c)+'"]');if(!th)return;const h=document.createElement('span');h.className='crm-drag-handle';h.textContent='⋮⋮';h.title='Arrastar coluna';h.draggable=true;(th.querySelector('.crm-th-inner')||th).prepend(h);h.addEventListener('dragstart',e=>{dragging=c;th.classList.add('crm-dragging');e.dataTransfer?.setData('text/plain',c)});h.addEventListener('dragend',()=>{dragging=null;clear()});th.addEventListener('dragover',e=>{if(!dragging||dragging===c)return;e.preventDefault();const r=th.getBoundingClientRect();after=e.clientX>r.left+r.width/2;clear();th.classList.add(after?'crm-drop-after':'crm-drop-before')});th.addEventListener('drop',e=>{if(!dragging||dragging===c)return;e.preventDefault();const next=order.filter(x=>x!==dragging);let i=next.indexOf(c);if(i<0)i=next.length;if(after)i++;next.splice(i,0,dragging);order=next;applyOrder();applyWidths();schedule(80);dragging=null;clear()});const rz=document.createElement('span');rz.className='crm-resizer';rz.title='Ajustar largura';th.appendChild(rz);rz.addEventListener('pointerdown',e=>{if(e.button!==0)return;e.preventDefault();e.stopPropagation();const x=e.clientX,w=th.getBoundingClientRect().width||widthFor(c)||120;document.body.style.userSelect='none';const mv=ev=>applyWidth(c,w+(ev.clientX-x),false);const up=ev=>{document.removeEventListener('pointermove',mv);document.body.style.userSelect='';applyWidth(c,w+(ev.clientX-x),true)};document.addEventListener('pointermove',mv);document.addEventListener('pointerup',up,{once:true})})});let sortCol='',sortDir=1;draggable.forEach(c=>{const th=grid.querySelector('thead th[data-col="'+CSS.escape(c)+'"]');if(!th)return;th.title=(th.title?th.title+' · ':'')+'Clique no título para ordenar';th.addEventListener('click',e=>{if(e.target.closest('.crm-drag-handle,.crm-resizer'))return;sortDir=sortCol===c?-sortDir:1;sortCol=c;const tbody=grid.tBodies[0];if(!tbody)return;const rows=[...tbody.rows].filter(r=>r.querySelector('[data-col]'));rows.sort((a,b)=>{const ca=a.querySelector('[data-col="'+CSS.escape(c)+'"]'),cb=b.querySelector('[data-col="'+CSS.escape(c)+'"]');let av=(ca?.dataset.sort??ca?.textContent??'').trim(),bv=(cb?.dataset.sort??cb?.textContent??'').trim();const an=Number(av.replace(/[^0-9,.-]/g,'').replace(/\./g,'').replace(',','.')),bn=Number(bv.replace(/[^0-9,.-]/g,'').replace(/\./g,'').replace(',','.'));let cmp=0;if(av!==''&&bv!==''&&Number.isFinite(an)&&Number.isFinite(bn)&&/[0-9]/.test(av)&&/[0-9]/.test(bv))cmp=an-bn;else cmp=av.localeCompare(bv,'pt-BR',{numeric:true,sensitivity:'base'});return cmp*sortDir});rows.forEach(r=>tbody.appendChild(r));grid.querySelectorAll('thead th').forEach(x=>x.classList.remove('crm-sort-asc','crm-sort-desc'));th.classList.add(sortDir===1?'crm-sort-asc':'crm-sort-desc')})});const reset=document.querySelector('[data-crm-grid-reset="'+CSS.escape(gridId)+'"]');reset?.addEventListener('click',()=>{visible=available.slice();order=draggable.slice();widths={};applyOrder();applyVisible();applyWidths();schedule(20)});})();
</script>
<?php }}

