.crm-advanced-wrap{overflow-x:auto;border:1px solid #e2e8f0;border-radius:12px}.crm-data-grid{width:100%;border-collapse:separate;border-spacing:0;table-layout:fixed;font-size:12px}.crm-data-grid th,.crm-data-grid td{padding:9px 10px;border-bottom:1px solid #e9eff8;border-right:1px solid #f1f5f9;vertical-align:middle;text-align:left;overflow:hidden;text-overflow:ellipsis}.crm-data-grid thead th{position:sticky;top:0;z-index:15;background:#f7faff;color:#243b70;font-size:10px;text-transform:uppercase;font-weight:900}.crm-data-grid tbody tr:nth-child(even) td{background:#eef3f9}.crm-data-grid tbody tr:hover td{background:#dbe7f5}.crm-th-inner{display:flex;align-items:center;gap:5px;min-height:22px;cursor:pointer}.crm-sort-asc .crm-th-inner:after{content:'▲';font-size:8px;margin-left:auto}.crm-sort-desc .crm-th-inner:after{content:'▼';font-size:8px;margin-left:auto}.crm-drag-handle{display:inline-flex;width:14px;justify-content:center;color:#94a3b8;cursor:grab;letter-spacing:-2px}.crm-resizer{position:absolute;right:-3px;top:0;width:7px;height:100%;cursor:col-resize}.crm-resizer:after{content:"";position:absolute;left:3px;top:20%;bottom:20%;width:1px;background:#c8d4e8}.crm-drop-before{box-shadow:inset 3px 0 0 #3558c9}.crm-drop-after{box-shadow:inset -3px 0 0 #3558c9}.crm-dragging{opacity:.55}.crm-col-hidden{display:none!important}.crm-grid-toolbar{display:flex;align-items:center;justify-content:flex-end;gap:8px;flex-wrap:wrap;margin-left:auto}.crm-grid-hint,.crm-grid-status{font-size:11px;color:#64748b;font-weight:700}.crm-grid-status.saved{color:#047857}.crm-grid-status.saving{color:#a16207}.crm-grid-status.error{color:#b91c1c}.crm-column-picker{position:relative}.crm-column-picker>summary{list-style:none}.crm-column-picker>summary::-webkit-details-marker{display:none}.crm-column-menu{position:absolute;right:0;top:calc(100% + 7px);z-index:140;min-width:230px;max-height:390px;overflow:auto;padding:12px;background:#fff;border:1px solid #d9e3f2;border-radius:12px;box-shadow:0 16px 38px rgba(15,35,80,.22)}.crm-column-menu strong{display:block;margin-bottom:8px}.crm-column-menu label{display:flex;gap:8px;align-items:center;padding:6px 2px;font-size:12px}.crm-column-menu input{width:16px;height:16px}.crm-column-menu .crm-btn{width:100%;margin-top:8px}.crm-data-grid .crm-actions-col{position:sticky;right:0;z-index:10;background:#fff!important;box-shadow:-5px 0 10px rgba(15,35,80,.05)}
.crm-temp-control{display:flex;gap:12px;align-items:center;border:1px solid #dbe3ed;border-radius:12px;padding:10px 12px;background:#f8fbff;min-height:104px}.crm-temp-meter{width:28px;height:82px;position:relative;flex:0 0 28px}.crm-temp-tube{position:absolute;left:9px;top:1px;width:10px;height:64px;border-radius:8px;background:#e2e8f0;border:2px solid #cbd5e1;overflow:hidden}.crm-temp-fill{position:absolute;left:0;right:0;bottom:0;height:var(--crm-temp-value);background:var(--crm-temp-color);transition:height .18s ease,background .18s ease}.crm-temp-bulb{position:absolute;bottom:0;left:3px;width:22px;height:22px;border-radius:50%;background:var(--crm-temp-color);border:3px solid #fff;box-shadow:0 0 0 2px #cbd5e1;transition:background .18s ease}.crm-temp-main{flex:1;min-width:0}.crm-temp-current{display:flex;align-items:baseline;gap:8px;margin-bottom:4px}.crm-temp-current strong{font-size:16px;color:var(--crm-temp-color)}.crm-temp-current span{font-size:11px;color:#64748b;font-weight:800}.crm-temp-main input[type=range]{width:100%;accent-color:var(--crm-temp-color);border:0!important;padding:0!important;background:transparent!important}.crm-temp-presets{display:flex;gap:6px;margin-top:5px;flex-wrap:wrap}.crm-temp-badge{--crm-temp-color:#2563eb;display:inline-flex;align-items:center;gap:4px;border:1px solid color-mix(in srgb,var(--crm-temp-color) 34%, white);background:color-mix(in srgb,var(--crm-temp-color) 10%, white);color:var(--crm-temp-color);border-radius:999px;padding:4px 7px;font-size:11px;white-space:nowrap}.crm-temp-badge small{font-weight:800;opacity:.78}.crm-message-audit{margin-top:7px;padding:8px 10px;border:1px solid #dbeafe;background:#eff6ff;border-radius:9px;font-size:11px}.crm-message-audit.sent{border-color:#bbf7d0;background:#f0fdf4;color:#166534}.crm-message-audit.error{border-color:#fecaca;background:#fef2f2;color:#991b1b}.crm-message-panel{border:1px solid #dbe3ed;border-radius:12px;padding:12px;background:#f8fbff}.crm-message-panel textarea{m