if (!function_exists('crm_page_end')) { function crm_page_end(): void { ?>
<script>
(()=>{document.querySelectorAll('[data-crm-temperature]').forEach(root=>{const range=root.querySelector('[data-crm-temp-range]'),hidden=root.querySelector('[data-crm-temp-value]'),label=root.querySelector('[data-crm-temp-label]'),score=root.querySelector('[data-crm-temp-score]');if(!range||!hidden)return;const paint=()=>{let v=Math.max(0,Math.min(100,Number(range.value||0)));let text='Frio',color='#2563EB';if(v>66){text='Quente';color='#DC2626'}else if(v>33){text='Morno';color='#F59E0B'}root.style.setProperty('--crm-temp-value',v+'%');root.style.setProperty('--crm-temp-color',color);hidden.value=String(Math.round(v));if(label)label.textContent=text;if(score)score.textContent=Math.round(v)+'%';};range.addEventListener('input',paint);root.querySelectorAll('[data-crm-temp-set]').forEach(btn=>btn.addEventListener('click',()=>{range.value=btn.getAttribute('data-crm-temp-set')||'20';paint();}));paint();});})();
</script>
